# src/lib/mando/__tests__/migraciones-mando.test.ts
  it("cada tabla tiene enable row level security", () => {
    const tablesWithRls = [
      "mando_ambitos",
      "mando_motores", 
      "mando_enjambres",
      "mando_tareas",
      "mando_eventos",
      "mando_chat",
      "mando_medidores",
      "mando_presupuesto",
    ];

    for (const tableName of tablesWithRls) {
      expect(content).toContain(`ALTER TABLE public.${tableName} ENABLE ROW LEVEL SECURITY`);
    }
  });

